import{_,o as a,c as r,a3 as e}from"./chunks/framework.DdpBa4_E.js";const c=JSON.parse('{"title":"致谢","description":"","frontmatter":{},"headers":[],"relativePath":"books/how-to-not-die-alone/22-致谢.md","filePath":"books/how-to-not-die-alone/22-致谢.md","lastUpdated":1794316978000}'),h={name:"books/how-to-not-die-alone/22-致谢.md"};function o(t,p,l,i,n,s){return a(),r("div",null,[...p[0]||(p[0]=[e('<h1 id="致谢" tabindex="-1">致谢 <a class="header-anchor" href="#致谢" aria-label="Permalink to &quot;致谢&quot;">​</a></h1><p>写书是一个人的事，除非你像我这样幸运，拥有一群值得信赖的朋友和顾问，愿意把你的项目当成自己的工作那样热心对待。</p><p>斯科特·梅耶·麦金尼，感谢你花了大量的时间编辑手稿，悉心守护我的精神健康，提醒我在关系科学领域不断探索。你就是我永远的合著人。</p><p>感谢我心爱的产品经理莫莉·格劳伯曼，你帮我创建写这本书所需的架构和各项支持。在这个过程中，你赢得了本的青睐，实至名归。感谢艾伦·休特，我的语法学家兼可靠的顾问，你那些及时、慷慨的反馈让我的观点、写作风格，甚至文中笑话的效果都进一步得到增强。成年后交朋友是一件很有趣的事。我花了八年时间才遇到你们二位；我每天都心怀感恩，并从未停止寻找。</p><p>康纳·迪曼德-尤曼，你能全身心投入这个项目中，真是我的幸运。因为你的助力，本书的每一章都变得更有趣、更深入了。</p><p>丽兹·福斯琳，我由衷钦佩你的创造力、智慧和才华。感谢你在本书出炉的全过程中坦率的反馈。和你在一起时，我总能做回真实的自己，这真是一份难得的馈赠。</p><p>金伯利·鲍德温，我们真是一对完美好搭档，感谢你一次次出手相救。</p><p>感谢布里特·尼尔森和汉娜·休斯，谢谢你们给了我这么棒的高雅品位。二位的设计天分在这段极具挑战的日子里为我提供了力量。</p><p>罗斯·伯恩，感谢你对初始提案以及本书的基础研究做出的宝贵贡献。</p><p>感谢托比·斯坦，我的调皮搭档。你就是友谊的典范，你在本书出炉的全过程中亲自给予的支持堪称无价。</p><p>感谢艾米丽·格拉夫，我这位西蒙与舒斯特出版社的不知疲倦的编辑。你很早就在我身上看到了这本书的构思，成为我每一步前行的坚定支持者，是我们一起完成了这个项目。</p><p>致我的终身益友们，是你们造就了我。我们的友谊就是我最大的成就。我们畅聊和一起相处的美好时光成了我生活中最大的期盼。我终于实现了这个多年的夙愿，能走到这一步，都是因为你们一直守护在我的身边。</p><p>达尼·海利策，我们的友谊跨越了30年，比所有的前任加起来都持久。你永远是我的家人。</p><p>拉娜·施莱辛格，我们是怎么在四岁时就找到了彼此的？我的一切都是我们俩的；你不仅仅是我朋友，你就是我的一部分。</p><p>艾莉森·康登、托里·西梅奥尼和米歇拉·德桑蒂斯，我们相互扶持、彼此指引，能取得今日的成就，真让我感到骄傲。能够在四维空间里共同生活，是多么幸运啊。</p><p>感谢泰莎·里昂-莱恩，我的姐姐。感谢你从一开始就和我一起谋划这本书。真高兴有你在身旁，和我度过一生。</p><p>玛塔贝尔·瓦瑟曼，我由衷欣赏你的热情、创意和智慧。我喜欢透过你的视角来观察我自己。</p><p>克里斯汀·伯曼，你就是湾区超级英雄联盟的队长。你从不拒绝，过去十年来，你的所有接纳促成了这么多美好的事，也包括这本书。</p><p>埃里克·托伦伯格，你自称是我的第一个“粉丝”。你的投资和对我工作的信心让很多事都成为可能。我们的友谊是我人生的一大幸事。</p><p>米莎·萨菲恩，你是一位实实在在的正人君子。</p><p>萨拉·索丁，本书的成书过程中，你慷慨地阅读了那么多大纲、草稿和文本，甚至挑灯夜战。你真是一个值得信赖的顾问和朋友。</p><p>塔拉·库莎，你的智慧和指导给了我追求激情的勇气。能与你以朋友相称，是我的荣幸。</p><p>感谢米凯拉·斯沃岑斯基，你在纽约的盛情款待为我开启了很多机会。没有什么比在你的沙发上和你聊天更让我开心的了。</p><p>如果没有导师们的慷慨和智慧，这本书就不会存在，他们都是行为和人际关系科学领域的巨人。</p><p>感谢丹·艾瑞里，在你身边学习是我能想到的学习行为科学的最好机会。你向我展示了如何过一种充实、实验性生活的方方面面。</p><p>感谢埃丝特·佩雷尔，你富有远见的工作为这本书铺平了道路。从我们第一次谈论我的父母，到我们谈论养育子女，你为我的生活增添了深度、复杂度和智慧。是你激励了我。</p><p>感谢约翰·戈特曼和朱莉·戈特曼——最原创的“人际关系大师”，感谢你们的指导和对这个领域的贡献。我和斯科特很早就参加了你们的研讨会，这让我们的关系更紧密了。</p><p>感谢伊莱·芬克尔，感谢你严谨的研究，这些研究塑造了我对爱和婚恋关系的看法。感谢你的善良和慷慨，感谢你给我提供了一起工作的机会。致艾莉森·芬克尔，我没有忘记你。感谢你欢迎我走进你们的家里，走进你们的心里。</p><p>感谢丹·琼斯、史蒂文·莱维特、海伦·费希尔、阿兰·德波顿、亚历山德拉·所罗门、巴里·施瓦茨、希娜·艾扬格、泰·田代，以及数十位分享了自己爱情生活的受访者，谢谢你们向我分享你们的智慧，是我们的这些交谈塑造了这本书。</p><p>致我早期的读者——拉娜、托丽、特莎、托比、克里斯汀、莫莉、艾伦、康纳、马塔贝列、丽兹、艾托沙·凯夫、亚历克西斯·科涅维奇、里贾纳·埃斯卡米利亚、迈克尔·弗维尔、劳拉·汤普森、法瑞尔·尤里、辛迪·梅耶、克雷格·米诺夫和菲奥娜·罗密里——感谢你们热忱的关注、创造性的建议和建设性的反馈。是你们把未来的读者从干瘪的笑话和晦涩的建议中解救了出来。</p><p>感谢迈克·王、杰西卡·科尔、瑞·包、泰勒·博斯梅尼、瑞安·迪克、布伦纳·赫尔、特莎、山姆·斯蒂尔、斯蒂芬妮·舍尔、黄美辰、乔什·霍洛维兹、娜塔莉·图尔萨尼和玛丽娜·阿加帕基斯的慷慨相助，组织了分工明确的晚宴，让众人在餐桌上畅谈、分享和反馈的各种想法，进一步丰富了本书。</p><p>感谢戴维·哈伯斯坦，感谢你慷慨地动用你那卓越的法律头脑帮助我，甚至在你休产假的第一周都不例外。</p><p>感谢艾莉森·亨特，我的经纪人，感谢你从一开始就对本书充满信心。再也找不到比你更坚定的拥护者了。</p><p>致我的客户，感谢你们信任我参与你们的爱情生活。你们向我展现的脆弱、奉献和热情是激励我写成此书的动力。</p><p>致我的家人，能写出这本书所需要的很多条件都来自你们的给予，来自你们对我的培养：让我变得坚韧、热爱语言，对自己的能力充满信心。感谢法瑞尔·尤里和本·萨克斯，能够拥有你们的爱和忠诚，让我感到无比幸运。感谢南希阿姨，你的婚姻为我设定了一个高标杆，你在婚姻生活这片疆土的“Kavanah”（目标）激励了我，并为本书提供了很多优秀的想法。感谢邦妮和约翰·尤里，是你们向我灌输了对阅读的热爱。我最大的愿望就是写一本书，并让我的父母读到。这个愿望实现了。</p><h2 id="关键谈话要点" tabindex="-1">关键谈话要点 <a class="header-anchor" href="#关键谈话要点" aria-label="Permalink to &quot;关键谈话要点&quot;">​</a></h2><ol><li>你这次谈话的目的是什么？（换句话说，你理想的成功谈话是什么样子的？）</li></ol><hr><hr><hr><ol start="2"><li>这次谈话中，你想要传递的核心信息是什么？</li></ol><hr><hr><hr><ol start="3"><li>你想用什么语气说话？你想避免什么语气？</li></ol><hr><hr><hr><ol start="4"><li>你希望用什么开场白？</li></ol><hr><hr><hr><ol start="5"><li>你需要说清楚哪些内容？</li></ol><hr><hr><hr><ol start="6"><li>你担心对方会有哪些反应？</li></ol><hr><hr><hr><ol start="7"><li>如果发生了这种情况，你打算怎么做？</li></ol><hr><hr><hr><p>8.你想怎样结束这次谈话？</p><hr><hr><hr><h2 id="自我反思表" tabindex="-1">自我反思表 <a class="header-anchor" href="#自我反思表" aria-label="Permalink to &quot;自我反思表&quot;">​</a></h2><p>说明</p><p>请你独自填写这张表，要对自己的需求做到诚实、开放。</p><h3 id="时间投入" tabindex="-1">时间投入 <a class="header-anchor" href="#时间投入" aria-label="Permalink to &quot;时间投入&quot;">​</a></h3><h4 id="可用的时间段" tabindex="-1">可用的时间段 <a class="header-anchor" href="#可用的时间段" aria-label="Permalink to &quot;可用的时间段&quot;">​</a></h4><p>我可以和伴侣在以下的时间段在一起（选择所有可用的时间段）：</p><p>□ 工作日的上午_______</p><p>□ 工作日的下午_______</p><p>□ 工作日的晚上_______</p><p>□ 周末上午_______</p><p>□ 周末下午_______</p><p>□ 周末晚上_______</p><p>理想情况下，我每周会和我的伴侣单独相处____次。</p><h4 id="惯例活动" tabindex="-1">惯例活动 <a class="header-anchor" href="#惯例活动" aria-label="Permalink to &quot;惯例活动&quot;">​</a></h4><p>在我现在或之前的恋情中，我最钟爱的三个惯例活动是（例如，周六去商店采购，约会看电影，周日在床上吃早餐等）：</p><p>1._______</p><p>2._______</p><p>3._______</p><p>未来，我希望形成下面这个新的惯例活动：</p><hr><hr><hr><h4 id="特别活动" tabindex="-1">特别活动 <a class="header-anchor" href="#特别活动" aria-label="Permalink to &quot;特别活动&quot;">​</a></h4><p>我喜欢和伴侣一起做以下三个特别活动（例如，旅行、去高档餐厅、一起上课等）：</p><p>1._______</p><p>2._______</p><p>3._______</p><h4 id="独处的时间" tabindex="-1">独处的时间 <a class="header-anchor" href="#独处的时间" aria-label="Permalink to &quot;独处的时间&quot;">​</a></h4><p>对于独处时间，我需要：</p><p>□ 很多（每天2小时）</p><p>□ 一般（每周至少一个晚上）</p><p>□ 不多（只要有机会独处就可以）</p><p>我很喜欢独自进行下列两项活动（例如，瑜伽、去商店采购等）：</p><p>1._______</p><p>2._______</p><h3 id="社交生活" tabindex="-1">社交生活 <a class="header-anchor" href="#社交生活" aria-label="Permalink to &quot;社交生活&quot;">​</a></h3><h4 id="朋友" tabindex="-1">朋友 <a class="header-anchor" href="#朋友" aria-label="Permalink to &quot;朋友&quot;">​</a></h4><p>我希望经常和朋友们一起进行的活动（或者某个传统）：</p><hr><hr><hr><p>我希望我的伴侣知道，下列这些朋友是我最关心和珍爱的：</p><p>1._______</p><p>2._______</p><p>3._______</p><p>我希望我的伴侣在我社交生活中的参与程度：</p><p>□ 完全融入（我们有共同的朋友和活动）</p><p>□ 部分融入（我们有共同的朋友和活动，但也有不同的小组和爱好）</p><p>□ 彼此分开（我喜欢和伴侣各自有不同的社交生活和爱好）</p><h4 id="家庭" tabindex="-1">家庭 <a class="header-anchor" href="#家庭" aria-label="Permalink to &quot;家庭&quot;">​</a></h4><p>我希望我们多久看望家人：</p><p>□ 每周至少一次</p><p>□ 每月至少一次</p><p>□ 一年几次</p><p>□ 一年一次</p><p>□ 几乎不看望</p><p>我希望在以下节日（或场合）与家人一起度过：</p><p>1._______</p><p>2._______</p><p>3._______</p><h3 id="情感需求" tabindex="-1">情感需求 <a class="header-anchor" href="#情感需求" aria-label="Permalink to &quot;情感需求&quot;">​</a></h3><h4 id="表达爱意" tabindex="-1">表达爱意 <a class="header-anchor" href="#表达爱意" aria-label="Permalink to &quot;表达爱意&quot;">​</a></h4><p>人们喜欢以不同的方式接受爱的表达。五种表达爱意的方式包括：肯定的言辞、共同相处的休闲时光、礼物、身体力行的服务、身体接触。</p><p>我钟爱的表达爱意的方式是：</p><p>□ 肯定的言词</p><p>□ 共同相处的休闲时光</p><p>□ 礼物</p><p>□ 身体力行的服务</p><p>□ 身体接触</p><h4 id="应对压力" tabindex="-1">应对压力 <a class="header-anchor" href="#应对压力" aria-label="Permalink to &quot;应对压力&quot;">​</a></h4><p>当我感到有压力的时候，我会做下面的事情来帮助自己放松（例如，洗澡、独处、找人谈心、散步、给朋友打电话等）：</p><hr><hr><p>当我感到有压力的时候，我希望伴侣以下列方式给予支持（选择所有适合的方式）：</p><p>□ 聆听我的发泄</p><p>□ 找一些事情做让我分心</p><p>□ 给我独处的时间</p><p>□ 提供解决方案</p><p>□ 其他方式：_______</p><h3 id="争吵" tabindex="-1">争吵 <a class="header-anchor" href="#争吵" aria-label="Permalink to &quot;争吵&quot;">​</a></h3><p>当我和伴侣的意见不一致时，我更喜欢用下列方式进行沟通（选择所有喜欢的方式）：</p><p>□ 面对面沟通</p><p>□ 邮件沟通</p><p>□ 发短信沟通</p><p>□ 其他方式：_______</p><h3 id="关于性爱" tabindex="-1">关于性爱 <a class="header-anchor" href="#关于性爱" aria-label="Permalink to &quot;关于性爱&quot;">​</a></h3><p>对我而言，性爱：</p><p>□ 非常重要</p><p>□ 比较重要</p><p>□ 不重要</p><p>理想情况下，我希望我的伴侣每周/月和我做爱___次。就排他性而言，我希望我们的关系是：</p><p>□ 绝对专一</p><p>□ 偶尔允许开放</p><p>□ 完全开放</p><p>□ 其他：_______</p><h2 id="亲密关系契约" tabindex="-1">亲密关系契约 <a class="header-anchor" href="#亲密关系契约" aria-label="Permalink to &quot;亲密关系契约&quot;">​</a></h2><p>说明</p><p>找个时间，最好挑一个让你们感到放松和浪漫的环境，和你的伴侣一起完成这份契约。首先填写“自我反思表”。然后，和对方分享你的表格，并且运用积极聆听的技巧，确保你的伴侣感受到你听懂了他要说的话，并且给他反馈。有必要的话，不必一次完成，可以休息一下。最后，在契约上签上你们的名字——别忘了接吻！</p><h3 id="契约正文" tabindex="-1">契约正文 <a class="header-anchor" href="#契约正文" aria-label="Permalink to &quot;契约正文&quot;">​</a></h3><p>我们认识到，长久的亲密关系需要双方付出努力。为此，我们选择对彼此持续投入感情，以促进我们爱得更深、更满足，不断成长。我们知道，在彼此相爱和感到幸福的时期投入精力加深、加强我们的亲密关系，要比到了困难时期再试图改善更容易。</p><p>鉴于上述认知，为确保这一亲密关系中各方的共同利益，起草该契约。</p><p>本契约由以下双方签订：</p><p>伴侣1：______</p><p>伴侣2：_______</p><p>（以下简称“伴侣双方”或“伴侣1”“伴侣2”）</p><p>本契约自___________签订生效。双方同意，在____检查和回顾契约，并进行修订。</p><h3 id="维系关系的承诺" tabindex="-1">维系关系的承诺 <a class="header-anchor" href="#维系关系的承诺" aria-label="Permalink to &quot;维系关系的承诺&quot;">​</a></h3><p>人际关系研究专家约翰·戈特曼和朱莉·戈特曼告诉我们，“承诺”是“情感交流的基本单位”。承诺可大可小，可以是口头的，也可以是书面的。这些承诺的核心就是维系关系。这些承诺采用的方式多种多样，可能是口头表达，可能是提问，还可能是肢体接触。它们可能是风趣的、严肃的，甚至是带有性意味的。每次你的伴侣提出一个承诺，你都有一个选择。你可以实现这个承诺，迎合伴侣的需求；或者“甩开”这个承诺，忽略维系关系的请求。那些和睦的亲密关系中，伴侣双方86%的时间都会实现彼此的承诺。那些岌岌可危的亲密关系中，伴侣双方只有33%的时间会实现彼此的承诺。经常实现彼此承诺的伴侣享受着一种充满信任、激情和满意性生活的亲密关系。</p><p>伴侣1：<em><strong><strong><strong>伴侣2：</strong></strong></strong></em></p><p>（签字）：<em><strong><strong><strong>（签字）：</strong></strong></strong></em></p><h3 id="时间投入-1" tabindex="-1">时间投入 <a class="header-anchor" href="#时间投入-1" aria-label="Permalink to &quot;时间投入&quot;">​</a></h3><h4 id="惯例活动-1" tabindex="-1">惯例活动 <a class="header-anchor" href="#惯例活动-1" aria-label="Permalink to &quot;惯例活动&quot;">​</a></h4><p>我们要在每周的以下时间单独在一起度过（在每周的这段时间里标注出见面的次数）：</p><p>□ 工作日的上午_______</p><p>□ 工作日的下午_______</p><p>□ 工作日的晚上_______</p><p>□ 周末上午_______</p><p>□ 周末下午_______</p><p>□ 周末晚上_______</p><p>我们每周将单独相处_____次。</p><p>我们每周会有___天/晚在一起时不用手机。</p><p>我们俩最喜欢一起做的惯例活动有（例如，去商店采购、约会看电影、在床上吃早餐等）：</p><hr><hr><hr><p>我们承诺，尽可能多地在一起进行这些活动。</p><p>如果我们每月错过了____次在一起的休闲时光，我们将采取以下措施弥补（例如，外出度周末、一起在家烹饪晚餐等）：</p><hr><hr><hr><p>我们同样希望尝试开发新的惯例活动。</p><p>从现在起到下次例行检查，我们会尝试新的惯例活动（例如，周日做顿早午餐、睡觉前谈论感恩的时刻等等）：</p><hr><hr><hr><h4 id="特别活动-1" tabindex="-1">特别活动 <a class="header-anchor" href="#特别活动-1" aria-label="Permalink to &quot;特别活动&quot;">​</a></h4><p>以下三项特别活动对我们而言非常重要（例如，旅行、去高档餐厅、一起上课等）：</p><p>1._______</p><p>2._______</p><p>3._______</p><p>我们承诺拨出时间，按照下列频率进行下列活动（例如，一起做饭——每周一次，等等）：</p><p>1._______</p><p>2._______</p><p>3._______</p><h4 id="独处的时间-1" tabindex="-1">独处的时间 <a class="header-anchor" href="#独处的时间-1" aria-label="Permalink to &quot;独处的时间&quot;">​</a></h4><p>我们都认同，每个人都需要一些独处时间给自己充电。</p><p>伴侣1</p><p>对于独处时间，我需要：</p><p>□ 很多（每天2小时）</p><p>□ 一般（每周至少一个晚上）</p><p>□ 不多（只要有机会独处就可以）</p><p>对我而言，独自进行的这项活动十分宝贵：</p><hr><p>伴侣2</p><p>对于独处时间，我需要：</p><p>□ 很多（每天2小时）</p><p>□ 一般（每周至少一个晚上）</p><p>□ 不多（只要有机会独处就可以）</p><p>对我而言，独自进行的这项活动十分宝贵：</p><hr><p>我们都明白，双方都需要独处的时间。</p><h4 id="朋友-1" tabindex="-1">朋友 <a class="header-anchor" href="#朋友-1" aria-label="Permalink to &quot;朋友&quot;">​</a></h4><p>我希望自己的朋友圈子：</p><p>□ 完全和对方分享</p><p>□ 有一定的重叠</p><p>□ 彼此分开</p><p>伴侣1</p><p>我承诺去结识伴侣2社交圈子中的下述三人：</p><p>1._______</p><p>2._______</p><p>3._______</p><p>伴侣2</p><p>我承诺去结识伴侣1社交圈子中的下述三人：</p><p>1._______</p><p>2._______</p><p>3._______</p><p>从现在起到下次例行检查，我们为社交生活设定一个目标（例如，一起参加更多的聚会、参加一个运动队、每月举办一次晚餐聚会等）：</p><hr><hr><hr><h4 id="家庭-1" tabindex="-1">家庭 <a class="header-anchor" href="#家庭-1" aria-label="Permalink to &quot;家庭&quot;">​</a></h4><p>我们将看望伴侣1的家人，频率如下：</p><p>□ 每周</p><p>□ 每月</p><p>□ 每年</p><p>□ 其他：_______</p><p>我们将看望伴侣2的家人，频率如下：</p><p>□ 每周</p><p>□ 每月</p><p>□ 每年</p><p>□ 其他：_______</p><p>节假日和特殊场合</p><p>以下节日/特殊场合的优先次序如下（例如，在某一方家里、某种信仰等）：</p><p>场合1：_______</p><p>我们希望这样度过：_______</p><p>场合2：_______</p><p>我们希望这样度过：_______</p><p>场合3：_______</p><p>我们希望这样度过：_______</p><h3 id="情感需求-1" tabindex="-1">情感需求 <a class="header-anchor" href="#情感需求-1" aria-label="Permalink to &quot;情感需求&quot;">​</a></h3><h4 id="表达爱意-1" tabindex="-1">表达爱意 <a class="header-anchor" href="#表达爱意-1" aria-label="Permalink to &quot;表达爱意&quot;">​</a></h4><p>我们知道，人们喜欢以不同的方式接受爱的表达。五种表达爱意的方式包括：肯定的言辞、共同相处的休闲时光、礼物、身体力行的服务、身体接触。</p><p>我们喜欢以下列方式接受爱意的表达：</p><p>伴侣1</p><p>我钟爱的表达爱意的方式是：</p><hr><p>伴侣2</p><p>我钟爱的表达爱意的方式是：</p><hr><h4 id="应对压力-1" tabindex="-1">应对压力 <a class="header-anchor" href="#应对压力-1" aria-label="Permalink to &quot;应对压力&quot;">​</a></h4><p>我们知道，每个人缓解压力的方式不一样。</p><p>伴侣1</p><p>我缓解压力的方法是：</p><hr><p>当我感到有压力的时候，伴侣这么做是对我的支持：</p><hr><p>伴侣2</p><p>我缓解压力的方法是：</p><hr><p>当我感到有压力的时候，伴侣这么做是对我的支持：</p><hr><h3 id="争吵-1" tabindex="-1">争吵 <a class="header-anchor" href="#争吵-1" aria-label="Permalink to &quot;争吵&quot;">​</a></h3><p>我们知道，在亲密关系中，有些行为是具有破坏性的。约翰·戈特曼和朱莉·戈特曼告诉我们，批评、鄙视、辩护或冷战的伴侣更有可能分手，待在一起也往往不开心。因此，这些行为被统称为亲密关系的“终结者”。</p><p>避免亲密关系的“终结者”</p><p>批评：我不会用言语攻击伴侣的性格或个性，我只会说我此刻的感受，对未来的不同做法提出具体要求。（例如，我会说“你总是不和我在一起，我感到很孤独。我希望我们一周有一晚能待在一起”，而不会说“你根本不在乎我”！）</p><p>鄙视：我不会攻击我的伴侣，我会营造一种欣赏的氛围，提醒自己注意伴侣的优点。</p><p>辩护：我不会文过饰非、推卸责任、自欺欺人，我会接受伴侣的反馈和观点，然后道歉。</p><p>冷战：当我们发生冲突，我感到情绪失控时，我不会选择逃离，而是停顿一下让自己冷静下来。当我觉得我可以再次开展有成效的谈话时，我会重新讨论刚才的内容。</p><p>伴侣1：<em><strong><strong><strong>伴侣2：</strong></strong></strong></em></p><p>（签字）：<em><strong><strong><strong>（签字）：</strong></strong></strong></em></p><p>当我们争吵时，我们更喜欢采取以下的沟通方式（例如，面对面，或通过书面形式交流等）：</p><p>伴侣1</p><p>我更喜欢这样：</p><hr><hr><hr><p>伴侣2</p><p>我更喜欢这样：</p><hr><hr><hr><p>当情绪失控时，人们可能会负面情绪泛滥。当我们感到被这种情绪淹没时，我们将用以下词语要求暂停，让彼此都冷静一下：_______________</p><h3 id="关于性爱-1" tabindex="-1">关于性爱 <a class="header-anchor" href="#关于性爱-1" aria-label="Permalink to &quot;关于性爱&quot;">​</a></h3><p>对我们而言，性爱：</p><p>□ 非常重要</p><p>□ 比较重要</p><p>□ 不重要</p><p>我们承诺，每___至少做爱__次。</p><p>就排他性而言，我们的关系是：</p><p>□ 绝对专一</p><p>□ 偶尔允许开放</p><p>□ 完全开放</p><p>□ 其他：_______</p><p>我们同意，共同遵循丹·萨维奇（Dan Savage）的GGG政策：当涉及我们的性生活时，我们倡导“好（good）、给予（give）和游戏（game）”。</p><p>伴侣1：_<strong><strong><strong>伴侣2：</strong></strong></strong></p><p>（签字）：<em><strong><strong><strong>（签字）：</strong></strong></strong></em></p><h3 id="结束语" tabindex="-1">结束语 <a class="header-anchor" href="#结束语" aria-label="Permalink to &quot;结束语&quot;">​</a></h3><p>我们明白，稳固的亲密关系需要伴侣双方不断努力。我们都承认，我们心中的优先事项、个人兴趣和个人感受可能——而且很可能——会随着时间的推移发生改变。我们承诺遵守上述条款，直到下次对契约进行回顾或我们的亲密关系结束。</p><p>伴侣1</p><p>姓名：_______</p><p>签字：_______</p><p>伴侣2</p><p>姓名：_______</p><p>签字：_______</p><p>日期：_______</p>',333)])])}const u=_(h,[["render",o]]);export{c as __pageData,u as default};
